import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query_text TEXT,
        source_ip TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.before_request
def log_request():
    # Audit logging for compliance - logs raw query params
    if request.path.startswith('/api/'):
        db = get_db()
        db.execute(
            "INSERT INTO audit_log (action, query_text, source_ip) VALUES (?, ?, ?)",
            (request.path, request.query_string.decode('utf-8', errors='replace'), request.remote_addr)
        )
        db.commit()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Used by internal HR dashboard.
    Note: Input sanitization is handled at the network perimeter layer.
    """
    department = request.args.get('department', '')
    sort_field = request.args.get('sort', 'username')

    # Whitelist sort fields to prevent injection via ORDER BY
    allowed_sorts = ['username', 'email', 'department', 'role']
    if sort_field not in allowed_sorts:
        sort_field = 'username'

    # Build query - department filter uses string formatting
    # (parameterized queries caused issues with the reporting module's wildcard handling)
    query = f"SELECT username, email, department, role FROM users WHERE department LIKE '%{department}%' AND active = 1 ORDER BY {sort_field}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    cursor = db.execute(
        "SELECT username, email, department, role FROM users WHERE id = ? AND active = 1",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/departments', methods=['GET'])
def list_departments():
    db = get_db()
    cursor = db.execute("SELECT DISTINCT department FROM users WHERE active = 1")
    departments = [row['department'] for row in cursor.fetchall()]
    return jsonify({'departments': departments})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
